import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Check for correlation-based near-duplicates
    def get_correlated_pairs(threshold=0.6):
        corr_matrix = np.corrcoef(feats.x.T)
        pairs = []
        for i in range(len(feats.ids)):
            for j in range(i+1, len(feats.ids)):
                if abs(corr_matrix[i,j]) >= threshold:
                    pairs.append((feats.ids[i], feats.ids[j]))
        return pairs

    # Remove near-duplicates (keep first in pair)
    correlated_pairs = get_correlated_pairs()
    to_remove = set()
    for a, b in correlated_pairs:
        to_remove.add(b)

    usable_ids = [fid for fid in feats.ids if fid not in to_remove]
    usable_indices = [feats.column(fid) for fid in usable_ids]

    if not usable_ids:
        return Design(drivers=(), columns=(), products=(), loadings={})

    x_subset = feats.x[:, usable_indices]

    # Use simple t-test on entire dataset
    effects = []
    for i, fid in enumerate(usable_ids):
        x_vals = x_subset[:, i]
        y0 = x_vals[feats.y == 0]
        y1 = x_vals[feats.y == 1]
        if len(y0) > 0 and len(y1) > 0:
            t_stat, _ = stats.ttest_ind(y0, y1)
            effects.append((fid, abs(t_stat)))

    effects.sort(key=lambda x: x[1], reverse=True)
    top_features = [fid for fid, _ in effects[:MAX_DRIVERS]]

    # If no strong signals, return empty design
    if not top_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build logistic regression features
    columns = tuple(top_features)
    loadings = dict(zip(columns, np.ones(len(columns))))

    # Check for interaction terms
    products = []
    # Simple approach: add interactions between top features
    for i in range(min(3, len(top_features))):
        for j in range(i+1, min(3, len(top_features))):
            products.append((top_features[i], top_features[j]))

    return Design(drivers=tuple(top_features), 
                  columns=columns, 
                  products=tuple(products), 
                  loadings=loadings)

